#!/usr/bin/env python3
"""Deterministic golden fixtures for the image container.

Run `python3 firmware/tests/fixtures/image_container/generate_fixtures.py`
from any directory to (re)write the .bin files and manifest.txt next to
this script. The Python tests and the C reader tests read the same bytes.
"""
import hashlib
import os
import struct
import sys
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
REPO_ROOT = os.path.abspath(os.path.join(HERE, "..", "..", "..", ".."))
if REPO_ROOT not in sys.path:
    sys.path.insert(0, REPO_ROOT)

from server import image_container as ic  # noqa: E402

PANEL_W, PANEL_H = 8, 4
ODD_W, ODD_H = 7, 3
FULL_W, FULL_H = 1200, 1600
LEGAL = (0, 1, 2, 3, 5, 6)

# name -> (expected class, palette_id, payload_len, panel override or None)
Case = tuple[bytes, str, int, int, "tuple[int, int] | None"]


def small_payload(size: int, seed: int = 0) -> bytes:
    """Nibble pairs drawn from the six legal codes, no padding nibble."""
    return bytes(
        (LEGAL[(i + seed) % 6] << 4) | LEGAL[(i * 2 + seed + 1) % 6]
        for i in range(size)
    )


def odd_payload() -> bytes:
    """7x3 = 21 pixels: 11 bytes whose final low (pad) nibble is 0."""
    data = bytearray(small_payload(11, seed=3))
    data[-1] &= 0xF0
    return bytes(data)


def full_size_pixels() -> bytes:
    return bytes(
        (LEGAL[(i * 5) % 6] << 4) | LEGAL[(i * 3 + 1) % 6]
        for i in range(ic.payload_size(FULL_W, FULL_H))
    )


def raw_header(
    *,
    magic: bytes = ic.MAGIC,
    version: int = 1,
    header_len: int = 24,
    flags: int = 0,
    width: int = PANEL_W,
    height: int = PANEL_H,
    pixel_format: int = 1,
    palette_id: int = 1,
    reserved: int = 0,
    payload_len: int = 16,
    crc: int = 0,
) -> bytes:
    return struct.pack(
        ic.HEADER_FORMAT, magic, version, header_len, flags, width, height,
        pixel_format, palette_id, reserved, payload_len, crc,
    )


def framed(payload: bytes, extra: bytes = b"", **fields: int) -> bytes:
    """Hand-packed container; the CRC covers `payload` unless overridden."""
    fields.setdefault("crc", zlib.crc32(payload))
    return raw_header(**fields) + extra + payload


def build_cases() -> dict[str, Case]:
    pay = small_payload(16)
    good = ic.encode_container(pay, PANEL_W, PANEL_H)
    odd = odd_payload()
    cases: dict[str, Case] = {
        "valid_v1_8x4": (good, "ok", 1, 16, None),
        "valid_v1_extended_header_8x4": (
            framed(pay, extra=b"\xde\xad\xbe\xef", header_len=28),
            "ok", 1, 16, None),
        "legacy_8x4": (pay, "legacy", 1, 16, None),
        "valid_v1_7x3": (
            ic.encode_container(odd, ODD_W, ODD_H), "ok", 1, 11,
            (ODD_W, ODD_H)),
        "legacy_7x3": (odd, "legacy", 1, 11, (ODD_W, ODD_H)),
        "bad_magic": (framed(pay, magic=b"SPIN"), "magic", 0, 0, None),
        "bad_version": (framed(pay, version=2), "version", 0, 0, None),
        "bad_header_len_short": (
            framed(pay, header_len=20), "header_len", 0, 0, None),
        "bad_header_len_past_buffer": (
            framed(pay, header_len=200), "header_len", 0, 0, None),
        "bad_flags_bit0": (framed(pay, flags=1), "flags", 0, 0, None),
        "bad_flags_unknown_bit": (
            framed(pay, flags=0x8000), "flags", 0, 0, None),
        "bad_reserved": (framed(pay, reserved=1), "reserved", 0, 0, None),
        "bad_pixel_format": (
            framed(pay, pixel_format=2), "pixel_format", 0, 0, None),
        "bad_palette": (framed(pay, palette_id=2), "palette", 0, 0, None),
        "bad_dimensions": (
            ic.encode_container(pay, PANEL_H, PANEL_W),
            "dimensions", 0, 0, None),
        "bad_payload_len": (
            framed(pay, payload_len=15), "length", 0, 0, None),
        "bad_total_length_short": (
            framed(pay[:-1]), "length", 0, 0, None),
        "bad_total_length_long": (
            framed(pay + b"\x00"), "length", 0, 0, None),
        "bad_crc": (
            framed(pay, crc=zlib.crc32(pay) ^ 1), "crc", 0, 0, None),
        "truncated_header": (
            ic.MAGIC + good[4:14], "truncated", 0, 0, None),
        "empty": (b"", "truncated", 0, 0, None),
        "bad_payload_len_overflow": (
            framed(pay, payload_len=0xFFFFFFFF), "length", 0, 0, None),
    }
    return cases


def build_all() -> dict[str, bytes]:
    """File name -> bytes for every .bin fixture."""
    return {f"{n}.bin": c[0] for n, c in build_cases().items()}


def manifest_text() -> str:
    full = ic.encode_container(full_size_pixels(), FULL_W, FULL_H)
    lines = [
        "# Golden fixtures for the image container, generated by",
        "# generate_fixtures.py. Whitespace separated; # starts a comment.",
        "# Case lines: <file> <expected> <palette_id> <payload_len>"
        " [panel_override <w> <h>]",
        f"panel {PANEL_W} {PANEL_H}",
    ]
    for name, (_, expected, palette, plen, override) in build_cases().items():
        line = f"{name}.bin {expected} {palette} {plen}"
        if override:
            line += f" panel_override {override[0]} {override[1]}"
        lines.append(line)
    lines += [
        f"check_crc32 {zlib.crc32(b'123456789'):08x}",
        f"full_size_crc32 {zlib.crc32(full[ic.HEADER_LEN:]):08x}",
        f"full_size_container_sha256 {hashlib.sha256(full).hexdigest()}",
    ]
    return "\n".join(lines) + "\n"


def main() -> None:
    for name, data in build_all().items():
        with open(os.path.join(HERE, name), "wb") as fh:
            fh.write(data)
    with open(os.path.join(HERE, "manifest.txt"), "w") as fh:
        fh.write(manifest_text())


if __name__ == "__main__":
    main()
